import java.util.*;
import java.util.stream.Collectors;

public class Demo3 {
    public static void main(String[] args) {
        List<String> list = new ArrayList<>(List.of("AA", "BBB", "CCCC", "DD", "EEE"));

        String result = list.stream()
            .collect(Collectors.joining("-"));

        System.out.println(result);
    }
}

import java.util.*;

public class Demo2 {
    public static void main(String[] args) {
        List<Integer> list = new ArrayList<>(List.of(1, 13, 11, 9));

        int sum = list.stream()
            .reduce(1, (a, b) -> a + b);

        System.out.println(sum);
    }
}

import java.util.*;

public class Demo {
    public static void main(String[] args) {
        List<Integer> list = new ArrayList<>(List.of(11, 34, 1, 13, 4));

        list.stream()
            .filter(x -> x > 10)
            .map(x -> x * 2)
            .peek(System.out::println)
            .sorted()
            .distinct()
            .forEach(System.out::println);
    }
}
